import java.io.*; import java.util.*; import java.util.stream.*; class PriceIndex implements Comparable<PriceIndex> { long price; int index; PriceIndex(long price, int index) { this.price = price; this.index = index; } public int compareTo(PriceIndex other) { return Long.compare(this.price, other.price); } } class Result { public static int minimumLoss(List<Long> price) { int n = price.size(); List<PriceIndex> list = new ArrayList<>(); for (int i = 0; i < n; i++) { list.add(new PriceIndex(price.get(i), i)); } Collections.sort(list); long minLoss = Long.MAX_VALUE; for (int i = 1; i < n; i++) { PriceIndex p1 = list.get(i - 1); PriceIndex p2 = list.get(i); if (p2.index < p1.index) { long loss = p2.price - p1.price; if (loss < minLoss) { minLoss = loss; } } } return (int) minLoss; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); String output = System.getenv("OUTPUT_PATH"); BufferedWriter bufferedWriter = output != null ? new BufferedWriter(new FileWriter(output)) : new BufferedWriter(new OutputStreamWriter(System.out)); int n = Integer.parseInt(bufferedReader.readLine().trim()); List<Long> price = Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Long::parseLong).collect(Collectors.toList()); int result = Result.minimumLoss(price); bufferedWriter.write(String.valueOf(result)); bufferedWriter.newLine(); bufferedReader.close(); bufferedWriter.close(); } }